<script>
(() => {
    const form = document.querySelector('[data-product-editor]');
    const mode = form.querySelector('[name="color_bar_pricing_type"]');
    const category = form.querySelector('[name="product_category_id"]');
    const reception = form.querySelector('[type="checkbox"][name="is_reception_usable"]');
    const colorBar = form.querySelector('[type="checkbox"][name="is_color_bar_usable"]');
    const update = () => {
        form.querySelector('[data-reception-disabled]').hidden = reception.checked;
        form.querySelector('[data-color-bar-disabled]').hidden = colorBar.checked;
        form.querySelector('[data-fixed-price-field]').hidden = mode.value === 'multiplier';
        form.querySelector('[data-gram-rate-field]').hidden = mode.value === 'fixed';
        const rate = category.selectedOptions[0]?.dataset.rate;
        form.querySelector('[data-category-rate]').textContent = rate !== undefined && rate !== '' ? '$' + Number(rate).toLocaleString('es-MX', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' por gr' : 'Selecciona una categoría con tarifa por gramo';
        form.querySelector('[data-pricing-help]').textContent = mode.value === 'both' ? 'Ambos: al agregar este producto, Color Bar elegirá Por aplicación o Por medida (gr). Sólo se cobrará la modalidad elegida.' : mode.value === 'multiplier' ? 'Por medida: Color Bar escribirá los gramos aplicados. La tarifa se obtiene de la categoría.' : 'Por aplicación: se registra una aplicación con el precio fijo indicado, sin pedir gramos.';
    };
    [mode, category, reception, colorBar].forEach(input => input.addEventListener('change', update));
    update();
})();
</script>
</x-layouts.app>
